using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using CrossVault.FoxDbf.Write;
using Xunit;

namespace CrossVault.FoxDbf.Tests;

/// <summary>
/// Field descriptors written by <see cref="DbfWriter.Create"/> compared byte for byte with VFP9-created tables
/// (<c>vfp_test/fieldflags/</c>, regenerated by <c>mkfieldflags.prg</c>). VFP9 sets the 0x04 (binary) flag
/// automatically on every type it stores in binary form — I, B, Y, T, Q, W — besides NOCPTRANS; NULL adds 0x02,
/// AUTOINC 0x08; and it stores names upper-cased in the table code page (razónsoc → RAZÓNSOC 0xD3,
/// œuvre → ŒUVRE 0x8C, ÿes → ŸES 0x9F).
/// </summary>
public sealed class DbfWriterFieldFlagsVfp9Tests : IDisposable
{
    private readonly SqlTestSupport.TempDir _dir = new();

    public void Dispose() => _dir.Dispose();

    public static IEnumerable<object[]> Tables() => new[]
    {
        new object[] { "alltypes", new[]
        {
            new DbfColumnDef("fc", 'C', 5), new DbfColumnDef("fn", 'N', 5, 2), new DbfColumnDef("ff", 'F', 5, 2),
            new DbfColumnDef("fi", 'I'), new DbfColumnDef("fb", 'B', 8, 2), new DbfColumnDef("fy", 'Y'),
            new DbfColumnDef("fd", 'D'), new DbfColumnDef("ft", 'T'), new DbfColumnDef("fl", 'L'),
            new DbfColumnDef("fm", 'M'), new DbfColumnDef("fg", 'G'), new DbfColumnDef("fq", 'Q', 5),
            new DbfColumnDef("fv", 'V', 5), new DbfColumnDef("fw", 'W'),
        } },
        new object[] { "nocp", new[]
        {
            new DbfColumnDef("cc", 'C', 5, binary: true), new DbfColumnDef("mm", 'M', binary: true),
            new DbfColumnDef("vv", 'V', 5, binary: true),
        } },
        new object[] { "nulls", new[]
        {
            new DbfColumnDef("nc", 'C', 5, nullable: true), new DbfColumnDef("ni", 'I', nullable: true),
            new DbfColumnDef("nt", 'T', nullable: true), new DbfColumnDef("ny", 'Y', nullable: true),
        } },
        new object[] { "autoinc", new[]
        {
            new DbfColumnDef("ai", 'I', autoIncrement: new DbfAutoIncrement(1)), new DbfColumnDef("plain", 'I'),
        } },
        new object[] { "names", new[]
        {
            new DbfColumnDef("lowcase", 'C', 5), new DbfColumnDef("MixedCase", 'C', 5),
            new DbfColumnDef("razónsoc", 'C', 5), new DbfColumnDef("œuvre", 'C', 5), new DbfColumnDef("ÿes", 'C', 5),
        } },
    };

    [Theory]
    [MemberData(nameof(Tables))]
    public void FieldDescriptors_AreByteIdenticalToVfp9(string table, DbfColumnDef[] columns)
    {
        string ours = Path.Combine(_dir.Path, table + ".dbf");
        using (DbfWriter.Create(ours, columns, new DbfCreateOptions { Overwrite = true })) { }

        var expected = Descriptors(File.ReadAllBytes(Fixtures.VfpTest(Path.Combine("fieldflags", table + ".dbf"))));
        var actual = Descriptors(File.ReadAllBytes(ours));

        Assert.Equal(expected.Count, actual.Count);
        for (int i = 0; i < expected.Count; i++)
            Assert.True(expected[i].SequenceEqual(actual[i]),
                $"{table} field {i + 1}: VFP9 {Convert.ToHexString(expected[i])} vs ours {Convert.ToHexString(actual[i])}");
    }

    /// <summary>The 32-byte field descriptors between the header and the 0x0D terminator.</summary>
    private static List<byte[]> Descriptors(byte[] dbf)
    {
        var list = new List<byte[]>();
        for (int p = 32; dbf[p] != 0x0D; p += 32)
            list.Add(dbf.AsSpan(p, 32).ToArray());
        return list;
    }
}
